/** Missing OPTIONAL storage and retention work must not become a cheap complete selector price. */
class NativeOptionalCostCompletenessTest {
	private static final int RIGHT_ROWS = 16;
	private static final LmdbNativeStaticPrior PRIOR = LmdbNativeStaticPrior.DEFAULT;

	enum Transformation {
		ORIGINAL,
		BENEFIT_FLAGS,
		INPUT_SPREAD,
		MAPPED_PROPOSAL
	}

	static Stream<Arguments> transformsAndDemand() {
		return Stream.of(Transformation.values())
				.flatMap(transform -> Stream.of(-1D, 1D, 4D).map(demand -> Arguments.of(transform, demand)));
	}

	@ParameterizedTest
	@MethodSource("transformsAndDemand")
	void unresolvedOptionalCannotBeatACompleteQuoteOnKnownSubtotal(Transformation transformation, double demand) {
		RowState row = row(new StatsSource(100_000L));
		try {
			LmdbNativeCostQuote optional = transform(optionalQuote(row, RIGHT_ROWS), transformation);
			LmdbNativeCostQuote complete = completeQuote(1000D);
			LmdbNativeCostVector known = optional.forSlice(demand);
			assertThat(PRIOR.expected(known)).as("the incomplete known subtotal really looks cheaper")
					.isLessThan(PRIOR.expected(complete.forSlice(demand)));
			assertThat(known.high(Feature.HASH_BUILD_ROW)).as("index/retention work remains unresolved").isInfinite();
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(
					candidate("optional", optional), candidate("complete", complete)), PRIOR, demand);
			assertThat(ranking.winner()).as("an unresolved OPTIONAL subtotal is not a complete price").isEqualTo(1);
			assertThat(ranking.eliminatedBy()[0]).containsIgnoringCase("incomplete").contains("OPTIONAL");
		} finally {
			row.memoryScope.close();
		}
	}

	@Test
	void positiveDemandKeepsTheKnownCompleteBuildEvenWhenItsTotalPriceIsIncomplete() {
		RowState row = row(new StatsSource(100_000L));
		try {
			LmdbNativeCostQuote quote = optionalQuote(row, RIGHT_ROWS);
			assertThat(quote.forSlice(1D).expected(Feature.DECODED_ROW))
					.as("one demanded output still requires the entire known RHS materialization")
					.isGreaterThanOrEqualTo(RIGHT_ROWS);
			assertThat(quote.forSlice(1D).high(Feature.HASH_BUILD_ROW)).isInfinite();
		} finally {
			row.memoryScope.close();
		}
	}

	@Test
	void zeroDemandDoesNotInheritInactiveOptionalUncertainty() {
		RowState row = row(new StatsSource(100_000L));
		try {
			LmdbNativeCostQuote optional = optionalQuote(row, RIGHT_ROWS);
			LmdbNativeCostQuote startup = new LmdbNativeCostQuote(
					LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 100D),
					LmdbNativeCostVector.zero(), RIGHT_ROWS, false, false);
			assertThat(optional.forSlice(0D).isZero()).isTrue();
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(
					candidate("optional", optional), candidate("startup", startup)), PRIOR, 0D);
			assertThat(ranking.winner()).isZero();
			assertThat(ranking.eliminatedBy()[0]).isNull();
		} finally {
			row.memoryScope.close();
		}
	}

	@Test
	void ordinaryEstimatedQuoteKeepsItsPriceDespiteAnUnboundedCeiling() {
		LmdbNativeCostQuote ordinary = LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.INTERPRETED_ROW, 0D, 1D, Double.POSITIVE_INFINITY),
				RIGHT_ROWS);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(
				candidate("ordinary", ordinary), candidate("complete", completeQuote(1000D))), PRIOR, -1D);
		assertThat(ranking.winner()).isZero();
		assertThat(ranking.eliminatedBy()[0]).isNull();
	}

	@Test
	void allIncompleteOptionalAlternativesUseStableFallbackInsteadOfSubtotalRanking() {
		RowState row = row(new StatsSource(100_000L));
		try {
			LmdbNativeCostQuote first = optionalQuote(row, RIGHT_ROWS);
			LmdbNativeCostQuote cheaperSubtotal = optionalQuote(row, 1);
			assertThat(PRIOR.expected(first.total())).isGreaterThan(PRIOR.expected(cheaperSubtotal.total()));
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(
					candidate("first", first), candidate("smaller-subtotal", cheaperSubtotal)), PRIOR, -1D);
			assertThat(ranking.winner()).as("neither missing total has an expected price to rank").isZero();
			assertThat(ranking.reason()).containsIgnoringCase("incomplete");
		} finally {
			row.memoryScope.close();
		}
	}

	@Test
	void finiteKnownWorkCannotBoundAnIncompleteTotalAndReplacementKeepsItsMarker() {
		LmdbNativeCostQuote partial = completeQuote(1D).withOptionalCost(OptionalCostCompleteness.MATERIALIZATION);
		assertThat(partial.bounded()).isFalse();
		try (var proposal = new LmdbNativeStrategyProposal<>(() -> "partial", 1D, "partial")
				.withCostQuote(partial)) {
			proposal.withCostQuote(completeQuote(2D));
			LmdbNativeCandidate<String> candidate = LmdbNativeStrategyProposal.candidate(proposal);
			assertThat(candidate.quote().optionalCost().incomplete()).isTrue();
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(candidate), PRIOR, 1D);
			assertThat(ranking.nanos()[0].high()).isInfinite();
			assertThat(ranking.expectedNanos()[0]).isFinite().isPositive();
			assertThat(ranking.incompleteOptional()[0]).contains("payload width");
			assertThat(ranking.reason()).contains("Incomplete OPTIONAL");
		}
	}

	@Test
	void decisionAndPlannedExplainIdentifyTheMissingWorkInsteadOfACompletePrice() {
		LmdbNativeCostQuote partial = completeQuote(1D).withOptionalCost(OptionalCostCompleteness.MATERIALIZATION);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(candidate("optional", partial)),
				PRIOR, 1D);
		LmdbNativeDecisionRecord.Entry entry = new LmdbNativeDecisionRecord.Entry("optional", true, null,
				ranking.nanos()[0], ranking.expectedNanos()[0], ranking.eliminatedBy()[0], partial.forSlice(1D),
				ranking.quotedExpectedNanos()[0], ranking.estimated()[0], ranking.incompleteOptional()[0]);
		LmdbNativeDecisionRecord decision = new LmdbNativeDecisionRecord(LmdbNativeDecisionPoint.ROW, "normal",
				List.of(entry), 0, ranking.reason());
		assertThat(entry.provenance()).isEqualTo("known subtotal");
		assertThat(decision.metric()).contains("known subtotal", "unbounded", "incomplete OPTIONAL", "spill");
		assertThat(decision.toStrategyDecision("optional").toText()).contains("Incomplete OPTIONAL", "stable fallback");
		QueryRoot target = new QueryRoot(new SingletonSet());
		OptionalExecutionStrategy.describe(new LeftJoinPlan(SingletonPlan.INSTANCE, SingletonPlan.INSTANCE,
				new int[0])).explainPlanned(target);
		assertThat(target.getStringMetricPlanned("nativeOptionalCostCompleteness"))
				.contains("incomplete", "payload width", "known work only");
	}

	@Test
	void anUnpricedFrontierWithMissingOptionalWorkKeepsStableOrder() {
		// Supply the known output work: otherwise forSlice adds an expected materialization count above its
		// zero floor, and the existing selector correctly treats these ordinary quotes as priced estimates.
		LmdbNativeCostVector output = LmdbNativeCostVector.point(Feature.OUTPUT_MATERIALIZATION, RIGHT_ROWS);
		LmdbNativeCostQuote first = LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.INTERPRETED_ROW, 20D, 20D, Double.POSITIVE_INFINITY).plus(output),
				RIGHT_ROWS);
		LmdbNativeCostQuote second = LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.INTERPRETED_ROW, 10D, 10D, Double.POSITIVE_INFINITY).plus(output),
				RIGHT_ROWS);
		assertThat(PRIOR.expected(first.forSlice(-1D))).isEqualTo(PRIOR.price(first.forSlice(-1D)).low());
		assertThat(PRIOR.expected(second.forSlice(-1D))).isEqualTo(PRIOR.price(second.forSlice(-1D)).low());
		assertThat(PRIOR.price(first.forSlice(-1D)).known()).isFalse();
		assertThat(PRIOR.price(second.forSlice(-1D)).known()).isFalse();
		LmdbNativeCostQuote missing = completeQuote(1D).withOptionalCost(OptionalCostCompleteness.MATERIALIZATION);
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(candidate("first", first),
				candidate("second", second), candidate("optional", missing)), PRIOR, -1D);
		assertThat(ranking.winner()).isZero();
		assertThat(ranking.reason()).contains("Incomplete OPTIONAL", "stable fallback");
	}

	private static LmdbNativeCandidate<String> candidate(String name, LmdbNativeCostQuote quote) {
		return LmdbNativeCandidate.of(name, quote, () -> name);
	}

	private static LmdbNativeCostQuote completeQuote(double rowWork) {
		return LmdbNativeCostQuote.streaming(LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, rowWork),
				RIGHT_ROWS);
	}

	private static LmdbNativeCostQuote optionalQuote(RowState row, int rightRows) {
		ValuesRow[] values = new ValuesRow[rightRows];
		for (int i = 0; i < values.length; i++) {
			values[i] = new ValuesRow(new int[] { 0 }, new long[] { i + 1L });
		}
		LeftJoinPlan plan = new LeftJoinPlan(SingletonPlan.INSTANCE, new ValuesPlan(values), new int[0]);
		// Fixed IDs prove the number of rows, not their lexical widths, residency, or future reuse distance.
		return LmdbNativePlanExecutionProfile.quote(plan, row, 0L, Mode.SEQUENTIAL);
	}

	private static LmdbNativeCostQuote transform(LmdbNativeCostQuote quote, Transformation transformation) {
		return switch (transformation) {
		case ORIGINAL -> quote;
		case BENEFIT_FLAGS -> quote.ordered(true).distinct(true).withOutputRows(RIGHT_ROWS);
		case INPUT_SPREAD -> quote.withInputSpread(LmdbNativeRowSpread.STRUCTURAL);
		case MAPPED_PROPOSAL -> {
			try (var proposal = new LmdbNativeStrategyProposal<>(() -> "optional", 1D, "optional")
					.withCostQuote(quote); var mapped = proposal.map(value -> value, "mapped-optional")) {
				yield LmdbNativeStrategyProposal.candidate(mapped).quote();
			}
		}
		};
	}
}
